import sys

def is_in_set(n, a, b):
    # Check if n is in the set generated by the rules
    if n == 1:
        return True
    if n % a == 0 and is_in_set(n // a, a, b):
        return True
    if n - b > 0 and is_in_set(n - b, a, b):
        return True
    return False

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1

    results = []

    for _ in range(t):
        n = int(data[index])
        a = int(data[index + 1])
        b = int(data[index + 2])
        index += 3

        if is_in_set(n, a, b):
            results.append("Yes")
        else:
            results.append("No")

    print("\n".join(results))

if __name__ == "__main__":
    main()
